// Modifications: rewritten in Rust for hodow_cts.
//
// Two deliberate shape changes from the C++, both of them collapses of a macro or a
// template explosion rather than a rewrite of any test:
//
//  - upstream's `TesterType` is generated by `GEN_PURE_SETTERS(X)`, so every state
//    appears three times (`X`, `X_SET_PURE_INT`, `X_SET_PURE_UINT`) and three switches
//    (`mapTesterToPname`, `isPureIntTester`, `isPureUintTester`) exist only to undo
//    that. Here the two axes stay separate - `TesterType` is the state and `Setter` is
//    which entry point writes it - so those three switches become one lookup and a
//    comparison.
//  - the five integer-valued texture cases (`TextureSwizzleCase`, `TextureWrapCase`,
//    `TextureFilterCase`, `TextureCompareModeCase`, `TextureCompareFuncCase`) and their
//    four sampler counterparts differ only in the initial value and the value list, so
//    each family is one body plus `integer_state_spec`.
//
// Upstream's `gl45` branch is left out: this port has no desktop-GL root, so no case
// can reach it. `es30`/`es31`/`es32` are all here, selected by context version exactly
// as `contextSupports` does.

use crate::gls::state_query_util::{
    QueryType, verify_state_sampler_param_float, verify_state_sampler_param_float_vec4,
    verify_state_sampler_param_integer, verify_state_sampler_param_integer_vec4,
    verify_state_sampler_param_normalized_i32_vec4, verify_state_sampler_param_unsigned_integer_vec4,
    verify_state_texture_object_boolean, verify_state_texture_param_float, verify_state_texture_param_float_vec4,
    verify_state_texture_param_integer, verify_state_texture_param_integer_vec4,
    verify_state_texture_param_normalized_i32_vec4, verify_state_texture_param_unsigned_integer_vec4,
};
use crate::glu::{ApiCase, ContextType, TestCaseGroup, add_api_case};
use crate::glw::{self, GLenum, GLint, GLuint};
use crate::tcu::Random;

const EXT_BORDER_CLAMP: &str = "GL_EXT_texture_border_clamp";
const EXT_SRGB_DECODE: &str = "GL_EXT_texture_sRGB_decode";

/// `gls::TextureStateQueryTests::TesterType`, without the `_SET_PURE_INT`/`_SET_PURE_UINT`
/// half of each name - see the file header.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum TesterType {
    TextureSwizzleR,
    TextureSwizzleG,
    TextureSwizzleB,
    TextureSwizzleA,
    TextureWrapS,
    TextureWrapT,
    TextureWrapR,
    TextureMagFilter,
    TextureMinFilter,
    TextureMinLod,
    TextureMaxLod,
    TextureBaseLevel,
    TextureMaxLevel,
    TextureCompareMode,
    TextureCompareFunc,
    TextureImmutableLevels,
    TextureImmutableFormat,
    DepthStencilTextureMode,
    TextureSrgbDecodeExt,
    TextureBorderColor,
    TextureWrapSClampToBorder,
    TextureWrapTClampToBorder,
    TextureWrapRClampToBorder,
}

/// The other half of upstream's `TesterType`: which entry point the case writes the
/// state through. `isPureIntTester` / `isPureUintTester` are `== Setter::PureInt` /
/// `== Setter::PureUint`.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Setter {
    /// `glTexParameter{i,f}[v]` / `glSamplerParameter{i,f}[v]`.
    Default,
    /// `glTexParameterIiv` / `glSamplerParameterIiv`.
    PureInt,
    /// `glTexParameterIuiv` / `glSamplerParameterIuiv`.
    PureUint,
}

impl Setter {
    fn is_pure(self) -> bool {
        self != Self::Default
    }
}

/// `mapTesterToPname`
fn map_tester_to_pname(tester: TesterType) -> GLenum {
    match tester {
        TesterType::TextureSwizzleR => glw::GL_TEXTURE_SWIZZLE_R,
        TesterType::TextureSwizzleG => glw::GL_TEXTURE_SWIZZLE_G,
        TesterType::TextureSwizzleB => glw::GL_TEXTURE_SWIZZLE_B,
        TesterType::TextureSwizzleA => glw::GL_TEXTURE_SWIZZLE_A,
        TesterType::TextureWrapS | TesterType::TextureWrapSClampToBorder => glw::GL_TEXTURE_WRAP_S,
        TesterType::TextureWrapT | TesterType::TextureWrapTClampToBorder => glw::GL_TEXTURE_WRAP_T,
        TesterType::TextureWrapR | TesterType::TextureWrapRClampToBorder => glw::GL_TEXTURE_WRAP_R,
        TesterType::TextureMagFilter => glw::GL_TEXTURE_MAG_FILTER,
        TesterType::TextureMinFilter => glw::GL_TEXTURE_MIN_FILTER,
        TesterType::TextureMinLod => glw::GL_TEXTURE_MIN_LOD,
        TesterType::TextureMaxLod => glw::GL_TEXTURE_MAX_LOD,
        TesterType::TextureBaseLevel => glw::GL_TEXTURE_BASE_LEVEL,
        TesterType::TextureMaxLevel => glw::GL_TEXTURE_MAX_LEVEL,
        TesterType::TextureCompareMode => glw::GL_TEXTURE_COMPARE_MODE,
        TesterType::TextureCompareFunc => glw::GL_TEXTURE_COMPARE_FUNC,
        TesterType::TextureImmutableLevels => glw::GL_TEXTURE_IMMUTABLE_LEVELS,
        TesterType::TextureImmutableFormat => glw::GL_TEXTURE_IMMUTABLE_FORMAT,
        TesterType::DepthStencilTextureMode => glw::GL_DEPTH_STENCIL_TEXTURE_MODE,
        TesterType::TextureSrgbDecodeExt => glw::GL_TEXTURE_SRGB_DECODE_EXT,
        TesterType::TextureBorderColor => glw::GL_TEXTURE_BORDER_COLOR,
    }
}

/// `querySupportsSigned`
fn query_supports_signed(query_type: QueryType) -> bool {
    !matches!(
        query_type,
        QueryType::TextureParamPureUnsignedInteger | QueryType::SamplerParamPureUnsignedInteger
    )
}

/// `isMultisampleTarget`
pub fn is_multisample_target(target: GLenum) -> bool {
    target == glw::GL_TEXTURE_2D_MULTISAMPLE || target == glw::GL_TEXTURE_2D_MULTISAMPLE_ARRAY
}

/// `isSamplerStateTester`
pub fn is_sampler_state_tester(tester: TesterType) -> bool {
    matches!(
        tester,
        TesterType::TextureWrapS
            | TesterType::TextureWrapT
            | TesterType::TextureWrapR
            | TesterType::TextureMagFilter
            | TesterType::TextureMinFilter
            | TesterType::TextureMinLod
            | TesterType::TextureMaxLod
            | TesterType::TextureCompareMode
            | TesterType::TextureCompareFunc
            | TesterType::TextureSrgbDecodeExt
            | TesterType::TextureBorderColor
            | TesterType::TextureWrapSClampToBorder
            | TesterType::TextureWrapTClampToBorder
            | TesterType::TextureWrapRClampToBorder
    )
}

/// `isLegalTesterForTarget`
pub fn is_legal_tester_for_target(target: GLenum, tester: TesterType) -> bool {
    // no 3d filtering on 2d targets
    if matches!(tester, TesterType::TextureWrapR | TesterType::TextureWrapRClampToBorder)
        && target != glw::GL_TEXTURE_3D
    {
        return false;
    }

    // no sampling on multisample
    if is_multisample_target(target) && is_sampler_state_tester(tester) {
        return false;
    }

    // no states in buffer
    target != glw::GL_TEXTURE_BUFFER
}

// ---------------------------------------------------------------------------------
// Required extensions - upstream's `RequiredExtensions` plus the es30/es31/es32
// `isCore*`/`get*Extension` pairs
// ---------------------------------------------------------------------------------

/// `RequiredExtensions::check`. Upstream throws `tcu::NotSupportedError` out of
/// `init()`, which a plain case body cannot do, so this reports and the caller returns.
fn check_required_extensions(case: &mut ApiCase<'_>, extensions: &[&str]) -> bool {
    let missing: Vec<&str> = extensions
        .iter()
        .copied()
        .filter(|ext| !case.context().context_info.is_extension_supported(ext))
        .collect();

    if missing.is_empty() {
        return true;
    }

    case.not_supported(format!("Test requires extension: {}", missing.join(", ")));
    false
}

/// `isCoreTextureTarget`
fn is_core_texture_target(context_type: ContextType, target: GLenum) -> bool {
    let es30 = matches!(
        target,
        glw::GL_TEXTURE_2D | glw::GL_TEXTURE_3D | glw::GL_TEXTURE_2D_ARRAY | glw::GL_TEXTURE_CUBE_MAP
    );
    let es31 = es30 || target == glw::GL_TEXTURE_2D_MULTISAMPLE;
    let es32 = es31
        || matches!(
            target,
            glw::GL_TEXTURE_2D_MULTISAMPLE_ARRAY | glw::GL_TEXTURE_BUFFER | glw::GL_TEXTURE_CUBE_MAP_ARRAY
        );

    if context_type.supports(3, 2) {
        es32
    } else if context_type.supports(3, 1) {
        es31
    } else {
        es30
    }
}

/// `getTextureTargetExtension`
fn texture_target_extension(target: GLenum) -> &'static [&'static str] {
    match target {
        glw::GL_TEXTURE_2D_MULTISAMPLE_ARRAY => &["GL_OES_texture_storage_multisample_2d_array"],
        glw::GL_TEXTURE_BUFFER => &["GL_EXT_texture_buffer"],
        glw::GL_TEXTURE_CUBE_MAP_ARRAY => &["GL_EXT_texture_cube_map_array"],
        other => panic!("{other:#x} is a core texture target"),
    }
}

/// `isCoreTextureParam`
fn is_core_texture_param(context_type: ContextType, pname: GLenum) -> bool {
    let es30 = matches!(
        pname,
        glw::GL_TEXTURE_BASE_LEVEL
            | glw::GL_TEXTURE_COMPARE_MODE
            | glw::GL_TEXTURE_COMPARE_FUNC
            | glw::GL_TEXTURE_MAG_FILTER
            | glw::GL_TEXTURE_MAX_LEVEL
            | glw::GL_TEXTURE_MAX_LOD
            | glw::GL_TEXTURE_MIN_FILTER
            | glw::GL_TEXTURE_MIN_LOD
            | glw::GL_TEXTURE_SWIZZLE_R
            | glw::GL_TEXTURE_SWIZZLE_G
            | glw::GL_TEXTURE_SWIZZLE_B
            | glw::GL_TEXTURE_SWIZZLE_A
            | glw::GL_TEXTURE_WRAP_S
            | glw::GL_TEXTURE_WRAP_T
            | glw::GL_TEXTURE_WRAP_R
            | glw::GL_TEXTURE_IMMUTABLE_FORMAT
            | glw::GL_TEXTURE_IMMUTABLE_LEVELS
    );
    let es31 = es30 || pname == glw::GL_DEPTH_STENCIL_TEXTURE_MODE;
    let es32 = es31 || pname == glw::GL_TEXTURE_BORDER_COLOR;

    if context_type.supports(3, 2) {
        es32
    } else if context_type.supports(3, 1) {
        es31
    } else {
        es30
    }
}

/// `getTextureParamExtension`
fn texture_param_extension(pname: GLenum) -> &'static [&'static str] {
    match pname {
        glw::GL_TEXTURE_SRGB_DECODE_EXT => &[EXT_SRGB_DECODE],
        glw::GL_TEXTURE_BORDER_COLOR => &[EXT_BORDER_CLAMP],
        other => panic!("{other:#x} is a core texture parameter"),
    }
}

/// `isCoreQuery` - the pure-integer entry points are core only from ES 3.2 on.
fn is_core_query(context_type: ContextType, query_type: QueryType) -> bool {
    if is_pure_query(query_type) {
        context_type.supports(3, 2)
    } else {
        true
    }
}

fn is_pure_query(query_type: QueryType) -> bool {
    matches!(
        query_type,
        QueryType::TextureParamPureInteger
            | QueryType::TextureParamPureUnsignedInteger
            | QueryType::TextureParamPureIntegerVec4
            | QueryType::TextureParamPureUnsignedIntegerVec4
            | QueryType::SamplerParamPureInteger
            | QueryType::SamplerParamPureUnsignedInteger
            | QueryType::SamplerParamPureIntegerVec4
            | QueryType::SamplerParamPureUnsignedIntegerVec4
    )
}

/// `isCoreTester`
fn is_core_tester(context_type: ContextType, tester: TesterType, setter: Setter) -> bool {
    let es30 = setter == Setter::Default
        && matches!(
            tester,
            TesterType::TextureSwizzleR
                | TesterType::TextureSwizzleG
                | TesterType::TextureSwizzleB
                | TesterType::TextureSwizzleA
                | TesterType::TextureWrapS
                | TesterType::TextureWrapT
                | TesterType::TextureWrapR
                | TesterType::TextureMagFilter
                | TesterType::TextureMinFilter
                | TesterType::TextureMinLod
                | TesterType::TextureMaxLod
                | TesterType::TextureBaseLevel
                | TesterType::TextureMaxLevel
                | TesterType::TextureCompareMode
                | TesterType::TextureCompareFunc
                | TesterType::TextureImmutableLevels
                | TesterType::TextureImmutableFormat
        );
    let es31 = es30 || (setter == Setter::Default && tester == TesterType::DepthStencilTextureMode);
    // ES 3.2 adds every pure setter of the states above plus the border-clamp testers.
    let es32 =
        es31 || matches!(
            tester,
            TesterType::TextureBorderColor
                | TesterType::TextureWrapSClampToBorder
                | TesterType::TextureWrapTClampToBorder
                | TesterType::TextureWrapRClampToBorder
        ) || (setter.is_pure() && tester != TesterType::TextureSrgbDecodeExt);

    if context_type.supports(3, 2) {
        es32
    } else if context_type.supports(3, 1) {
        es31
    } else {
        es30
    }
}

/// `getTesterExtension`
fn tester_extension(context_type: ContextType, tester: TesterType, setter: Setter) -> &'static [&'static str] {
    if context_type.supports(3, 2) {
        // only TESTER_TEXTURE_SRGB_DECODE_EXT and its pure setters are left
        return &[EXT_SRGB_DECODE];
    }

    match (tester, setter) {
        (TesterType::TextureSrgbDecodeExt, Setter::Default) => &[EXT_SRGB_DECODE],
        (TesterType::TextureSrgbDecodeExt, _) => &[EXT_SRGB_DECODE, EXT_BORDER_CLAMP],
        _ => &[EXT_BORDER_CLAMP],
    }
}

/// `TextureTest::init` / `SamplerTest::init` - the union of what the target, the
/// parameter, the query and the tester each need.
fn require_texture_test_support(
    case: &mut ApiCase<'_>,
    target: Option<GLenum>,
    tester: TesterType,
    setter: Setter,
    query_type: QueryType,
) -> bool {
    let context_type = case.context().context_type();
    let pname = map_tester_to_pname(tester);
    let mut extensions: Vec<&'static str> = Vec::new();
    // `RequiredExtensions::add` keeps the first mention of each and drops the rest.
    let add = |extensions: &mut Vec<&'static str>, added: &[&'static str]| {
        for ext in added {
            if !extensions.contains(ext) {
                extensions.push(ext);
            }
        }
    };

    // target - a sampler case has none
    if let Some(target) = target
        && !is_core_texture_target(context_type, target)
    {
        add(&mut extensions, texture_target_extension(target));
    }

    // param
    if !is_core_texture_param(context_type, pname) {
        add(&mut extensions, texture_param_extension(pname));
    }

    // query
    if !is_core_query(context_type, query_type) {
        add(&mut extensions, &[EXT_BORDER_CLAMP]);
    }

    // test type
    if !is_core_tester(context_type, tester, setter) {
        add(&mut extensions, tester_extension(context_type, tester, setter));
    }

    check_required_extensions(case, &extensions)
}

