fn sampler_parameter_pure(case: &mut ApiCase<'_>, setter: Setter, sampler: GLuint, pname: GLenum, value: GLint) {
    // SAFETY: one value for a single-valued parameter.
    unsafe {
        match setter {
            Setter::PureInt => case.gl().sampler_parameter_iiv(sampler, pname, &value),
            #[expect(clippy::cast_sign_loss, reason = "upstream assigns the same GLenum to a GLuint")]
            Setter::PureUint => case.gl().sampler_parameter_iuiv(sampler, pname, &(value as GLuint)),
            Setter::Default => panic!("not a pure setter"),
        }
    }
    case.expect_error(glw::GL_NO_ERROR);
}

/// The values a tester's `Set` section walks through, and the value the state starts at.
///
/// Every integer-valued case has the same shape - check the initial value, set each
/// value with the `i` entry point and re-read it, then set each one again with the `f`
/// entry point to check the unit conversion - so it is written once here.
struct IntegerStateSpec {
    initial: GLint,
    values: Vec<GLint>,
}

fn integer_state_spec(pname: GLenum) -> IntegerStateSpec {
    match pname {
        glw::GL_TEXTURE_SWIZZLE_R
        | glw::GL_TEXTURE_SWIZZLE_G
        | glw::GL_TEXTURE_SWIZZLE_B
        | glw::GL_TEXTURE_SWIZZLE_A => IntegerStateSpec {
            initial: match pname {
                glw::GL_TEXTURE_SWIZZLE_R => glw::GL_RED as GLint,
                glw::GL_TEXTURE_SWIZZLE_G => glw::GL_GREEN as GLint,
                glw::GL_TEXTURE_SWIZZLE_B => glw::GL_BLUE as GLint,
                _ => glw::GL_ALPHA as GLint,
            },
            values: vec![
                glw::GL_RED as GLint,
                glw::GL_GREEN as GLint,
                glw::GL_BLUE as GLint,
                glw::GL_ALPHA as GLint,
                glw::GL_ZERO as GLint,
                glw::GL_ONE as GLint,
            ],
        },

        glw::GL_TEXTURE_WRAP_S | glw::GL_TEXTURE_WRAP_T | glw::GL_TEXTURE_WRAP_R => IntegerStateSpec {
            initial: glw::GL_REPEAT as GLint,
            values: vec![
                glw::GL_CLAMP_TO_EDGE as GLint,
                glw::GL_REPEAT as GLint,
                glw::GL_MIRRORED_REPEAT as GLint,
            ],
        },

        glw::GL_TEXTURE_MAG_FILTER => IntegerStateSpec {
            initial: glw::GL_LINEAR as GLint,
            values: vec![glw::GL_NEAREST as GLint, glw::GL_LINEAR as GLint],
        },

        glw::GL_TEXTURE_MIN_FILTER => IntegerStateSpec {
            initial: glw::GL_NEAREST_MIPMAP_LINEAR as GLint,
            values: vec![
                glw::GL_NEAREST as GLint,
                glw::GL_LINEAR as GLint,
                glw::GL_NEAREST_MIPMAP_NEAREST as GLint,
                glw::GL_NEAREST_MIPMAP_LINEAR as GLint,
                glw::GL_LINEAR_MIPMAP_NEAREST as GLint,
                glw::GL_LINEAR_MIPMAP_LINEAR as GLint,
            ],
        },

        glw::GL_TEXTURE_COMPARE_MODE => IntegerStateSpec {
            initial: glw::GL_NONE as GLint,
            values: vec![glw::GL_COMPARE_REF_TO_TEXTURE as GLint, glw::GL_NONE as GLint],
        },

        glw::GL_TEXTURE_COMPARE_FUNC => IntegerStateSpec {
            initial: glw::GL_LEQUAL as GLint,
            values: vec![
                glw::GL_LEQUAL as GLint,
                glw::GL_GEQUAL as GLint,
                glw::GL_LESS as GLint,
                glw::GL_GREATER as GLint,
                glw::GL_EQUAL as GLint,
                glw::GL_NOTEQUAL as GLint,
                glw::GL_ALWAYS as GLint,
                glw::GL_NEVER as GLint,
            ],
        },

        other => panic!("{other:#x} has no integer state spec"),
    }
}

// ---------------------------------------------------------------------------------
// Texture cases
// ---------------------------------------------------------------------------------

/// `TextureSwizzleCase`, `TextureWrapCase`, `TextureFilterCase`, `TextureCompareModeCase`
/// and `TextureCompareFuncCase` - one body, because upstream's five differ only in the
/// table `integer_state_spec` returns.
fn texture_integer_state_case(
    case: &mut ApiCase<'_>,
    target: GLenum,
    pname: GLenum,
    setter: Setter,
    query_type: QueryType,
) {
    let spec = integer_state_spec(pname);

    with_bound_texture(case, target, |case| {
        // Initial
        if !setter.is_pure() {
            verify_state_texture_param_integer(case, target, pname, spec.initial, query_type);
        }

        // Set
        if setter.is_pure() {
            for &value in &spec.values {
                tex_parameter_pure(case, setter, target, pname, value);
                verify_state_texture_param_integer(case, target, pname, value, query_type);
            }
        } else {
            for &value in &spec.values {
                tex_parameteri(case, target, pname, value);
                verify_state_texture_param_integer(case, target, pname, value, query_type);
            }

            // check unit conversions with float
            for &value in &spec.values {
                #[expect(clippy::cast_precision_loss, reason = "a GL enum is small enough to be exact in f32")]
                let as_float = value as f32;
                tex_parameterf(case, target, pname, as_float);
                verify_state_texture_param_integer(case, target, pname, value, query_type);
            }
        }
    });
}

/// `TextureLODCase`
fn texture_lod_case(case: &mut ApiCase<'_>, target: GLenum, pname: GLenum, setter: Setter, query_type: QueryType) {
    let initial_value = if pname == glw::GL_TEXTURE_MIN_LOD { -1000 } else { 1000 };

    with_bound_texture(case, target, |case| {
        if (query_supports_signed(query_type) || initial_value >= 0) && !setter.is_pure() {
            verify_state_texture_param_integer(case, target, pname, initial_value, query_type);
        }

        let num_iterations = 20;
        let mut rnd = Random::new(0xabcdef);

        match setter {
            Setter::PureInt => {
                for _ in 0..num_iterations {
                    let reference = rnd.get_int(-1000, 1000);
                    tex_parameter_pure(case, setter, target, pname, reference);
                    #[expect(clippy::cast_precision_loss, reason = "the range is far inside f32's exact integers")]
                    let as_float = reference as f32;
                    verify_state_texture_param_float(case, target, pname, as_float, query_type);
                }
            }
            Setter::PureUint => {
                for _ in 0..num_iterations {
                    let reference = rnd.get_int(0, 1000);
                    tex_parameter_pure(case, setter, target, pname, reference);
                    #[expect(clippy::cast_precision_loss, reason = "as above")]
                    let as_float = reference as f32;
                    verify_state_texture_param_float(case, target, pname, as_float, query_type);
                }
            }
            Setter::Default => {
                let min_limit = if query_supports_signed(query_type) { -1000 } else { 0 };

                for _ in 0..num_iterations {
                    #[expect(clippy::cast_precision_loss, reason = "as above")]
                    let reference = rnd.get_float_range(min_limit as f32, 1000.0);
                    tex_parameterf(case, target, pname, reference);
                    verify_state_texture_param_float(case, target, pname, reference, query_type);
                }

                // check unit conversions with int
                for _ in 0..num_iterations {
                    let reference = rnd.get_int(min_limit, 1000);
                    tex_parameteri(case, target, pname, reference);
                    #[expect(clippy::cast_precision_loss, reason = "as above")]
                    let as_float = reference as f32;
                    verify_state_texture_param_float(case, target, pname, as_float, query_type);
                }
            }
        }
    });
}

/// `TextureLevelCase`
fn texture_level_case(case: &mut ApiCase<'_>, target: GLenum, pname: GLenum, setter: Setter, query_type: QueryType) {
    let initial_value = if pname == glw::GL_TEXTURE_BASE_LEVEL { 0 } else { 1000 };

    with_bound_texture(case, target, |case| {
        if !setter.is_pure() {
            verify_state_texture_param_integer(case, target, pname, initial_value, query_type);
        }

        if is_multisample_target(target) {
            // only 0 allowed
            tex_parameteri(case, target, pname, 0);
            verify_state_texture_param_integer(case, target, pname, 0, query_type);

            tex_parameterf(case, target, pname, 0.0);
            verify_state_texture_param_integer(case, target, pname, 0, query_type);
            return;
        }

        let num_iterations = 20;
        let mut rnd = Random::new(0xabcdef);

        if setter.is_pure() {
            for _ in 0..num_iterations {
                let reference = rnd.get_int(0, 64000);
                tex_parameter_pure(case, setter, target, pname, reference);
                verify_state_texture_param_integer(case, target, pname, reference, query_type);
            }
            return;
        }

        for _ in 0..num_iterations {
            let reference = rnd.get_int(0, 64000);
            tex_parameteri(case, target, pname, reference);
            verify_state_texture_param_integer(case, target, pname, reference, query_type);
        }

        // check unit conversions with float. Offsets O are chosen so that for any
        // integer z and any o in O, roundToClosestInt(z + o) == z.
        const NON_SIGNIFICANT_OFFSETS: [f32; 4] = [-0.45, -0.25, 0.0, 0.45];

        for _ in 0..30 {
            let reference = rnd.get_int(1, 64000);
            for offset in NON_SIGNIFICANT_OFFSETS {
                #[expect(clippy::cast_precision_loss, reason = "64000 is exact in f32")]
                let as_float = reference as f32;
                tex_parameterf(case, target, pname, as_float + offset);
                verify_state_texture_param_integer(case, target, pname, reference, query_type);
            }
        }
    });
}

/// `TextureImmutableLevelsCase`
fn texture_immutable_levels_case(case: &mut ApiCase<'_>, target: GLenum, pname: GLenum, query_type: QueryType) {
    with_bound_texture(case, target, |case| {
        verify_state_texture_param_integer(case, target, pname, 0, query_type);
    });

    if is_multisample_target(target) {
        // no levels
        with_bound_texture(case, target, |case| {
            // SAFETY: a bound texture of `target`.
            unsafe {
                if target == glw::GL_TEXTURE_2D_MULTISAMPLE {
                    case.gl()
                        .tex_storage_2d_multisample(target, 2, glw::GL_RGB8, 64, 64, glw::FALSE);
                } else {
                    case.gl()
                        .tex_storage_3d_multisample(target, 2, glw::GL_RGB8, 64, 64, 2, glw::FALSE);
                }
            }
            case.expect_error(glw::GL_NO_ERROR);

            verify_state_texture_param_integer(case, target, pname, 1, query_type);
        });
        return;
    }

    for level in 1..=7 {
        with_bound_texture(case, target, |case| {
            // SAFETY: a bound texture of `target`, sized for every level asked for.
            unsafe {
                match target {
                    glw::GL_TEXTURE_2D | glw::GL_TEXTURE_CUBE_MAP => {
                        case.gl().tex_storage_2d(target, level, glw::GL_RGB8, 64, 64)
                    }
                    glw::GL_TEXTURE_CUBE_MAP_ARRAY => {
                        case.gl().tex_storage_3d(target, level, glw::GL_RGB8, 64, 64, 6 * 2)
                    }
                    _ => case.gl().tex_storage_3d(target, level, glw::GL_RGB8, 64, 64, 64),
                }
            }
            case.expect_error(glw::GL_NO_ERROR);

            verify_state_texture_param_integer(case, target, pname, level, query_type);
        });
    }
}

/// `TextureImmutableFormatCase`
fn texture_immutable_format_case(case: &mut ApiCase<'_>, target: GLenum, pname: GLenum, query_type: QueryType) {
    with_bound_texture(case, target, |case| {
        verify_state_texture_param_integer(case, target, pname, 0, query_type);
    });

    // Immutable
    with_bound_texture(case, target, |case| {
        // SAFETY: a bound texture of `target`.
        unsafe {
            match target {
                glw::GL_TEXTURE_2D | glw::GL_TEXTURE_CUBE_MAP => {
                    case.gl().tex_storage_2d(target, 1, glw::GL_RGBA8, 32, 32)
                }
                glw::GL_TEXTURE_2D_ARRAY | glw::GL_TEXTURE_3D => {
                    case.gl().tex_storage_3d(target, 1, glw::GL_RGBA8, 32, 32, 8)
                }
                glw::GL_TEXTURE_2D_MULTISAMPLE => {
                    case.gl()
                        .tex_storage_2d_multisample(target, 2, glw::GL_RGB8, 64, 64, glw::FALSE)
                }
                glw::GL_TEXTURE_2D_MULTISAMPLE_ARRAY => {
                    case.gl()
                        .tex_storage_3d_multisample(target, 2, glw::GL_RGB8, 64, 64, 2, glw::FALSE)
                }
                _ => case.gl().tex_storage_3d(target, 1, glw::GL_RGBA8, 32, 32, 6 * 2),
            }
        }
        case.expect_error(glw::GL_NO_ERROR);

        verify_state_texture_param_integer(case, target, pname, 1, query_type);
    });

    // no mutable
    if is_multisample_target(target) {
        return;
    }

    // test mutable
    with_bound_texture(case, target, |case| {
        // SAFETY: a bound texture of `target`; a null pointer allocates without data.
        unsafe {
            match target {
                glw::GL_TEXTURE_2D => case.gl().tex_image_2d(
                    target,
                    0,
                    glw::GL_RGBA8 as GLint,
                    32,
                    32,
                    0,
                    glw::GL_RGBA,
                    glw::GL_UNSIGNED_BYTE,
                    std::ptr::null(),
                ),
                glw::GL_TEXTURE_CUBE_MAP => case.gl().tex_image_2d(
                    glw::GL_TEXTURE_CUBE_MAP_NEGATIVE_Y,
                    0,
                    glw::GL_RGBA8 as GLint,
                    32,
                    32,
                    0,
                    glw::GL_RGBA,
                    glw::GL_UNSIGNED_BYTE,
                    std::ptr::null(),
                ),
                glw::GL_TEXTURE_CUBE_MAP_ARRAY => case.gl().tex_image_3d(
                    target,
                    0,
                    glw::GL_RGBA8 as GLint,
                    32,
                    32,
                    6 * 2,
                    0,
                    glw::GL_RGBA,
                    glw::GL_UNSIGNED_BYTE,
                    std::ptr::null(),
                ),
                _ => case.gl().tex_image_3d(
                    target,
                    0,
                    glw::GL_RGBA8 as GLint,
                    32,
                    32,
                    8,
                    0,
                    glw::GL_RGBA,
                    glw::GL_UNSIGNED_BYTE,
                    std::ptr::null(),
                ),
            }
        }
        case.expect_error(glw::GL_NO_ERROR);

        verify_state_texture_param_integer(case, target, pname, 0, query_type);
    });
}

/// `DepthStencilModeCase` and `TextureSRGBDecodeCase` - upstream's two are the same
/// body over a different pair of values.
fn texture_toggle_state_case(
    case: &mut ApiCase<'_>,
    target: GLenum,
    pname: GLenum,
    setter: Setter,
    query_type: QueryType,
    initial: GLint,
    other: GLint,
) {
    with_bound_texture(case, target, |case| {
        if !setter.is_pure() {
            // Initial
            verify_state_texture_param_integer(case, target, pname, initial, query_type);

            // Toggle
            tex_parameteri(case, target, pname, other);
            verify_state_texture_param_integer(case, target, pname, other, query_type);

            tex_parameteriv(case, target, pname, initial);
            verify_state_texture_param_integer(case, target, pname, initial, query_type);

            #[expect(clippy::cast_precision_loss, reason = "a GL enum is small enough to be exact in f32")]
            let other_float = other as f32;
            tex_parameterf(case, target, pname, other_float);
            verify_state_texture_param_integer(case, target, pname, other, query_type);

            #[expect(clippy::cast_precision_loss, reason = "as above")]
            let initial_float = initial as f32;
            tex_parameterfv(case, target, pname, initial_float);
            verify_state_texture_param_integer(case, target, pname, initial, query_type);
        } else {
            tex_parameter_pure(case, setter, target, pname, other);
            verify_state_texture_param_integer(case, target, pname, other, query_type);

            tex_parameter_pure(case, setter, target, pname, initial);
            verify_state_texture_param_integer(case, target, pname, initial, query_type);
        }
    });
}

/// `TextureWrapClampToBorderCase`
fn texture_wrap_clamp_to_border_case(case: &mut ApiCase<'_>, target: GLenum, pname: GLenum, query_type: QueryType) {
    with_bound_texture(case, target, |case| {
        tex_parameteri(case, target, pname, glw::GL_CLAMP_TO_BORDER_EXT as GLint);
        verify_state_texture_param_integer(case, target, pname, glw::GL_CLAMP_TO_BORDER_EXT as GLint, query_type);

        tex_parameteri(case, target, pname, glw::GL_REPEAT as GLint);

        #[expect(clippy::cast_precision_loss, reason = "a GL enum is small enough to be exact in f32")]
        let clamp_to_border = glw::GL_CLAMP_TO_BORDER_EXT as f32;
        tex_parameterf(case, target, pname, clamp_to_border);

        verify_state_texture_param_integer(case, target, pname, glw::GL_CLAMP_TO_BORDER_EXT as GLint, query_type);
    });
}

/// The border colours upstream's two `*BorderColorCase`s write, shared so the texture
/// and sampler halves cannot drift apart.
const BORDER_COLOR_PURE_INT: [GLint; 4] = [0x7FFF_FFFF, -2, 3, -128];
const BORDER_COLOR_PURE_UINT: [GLuint; 4] = [0x0800_0000, 2, 3, 128];
const BORDER_COLOR_FLOAT: [f32; 4] = [0.25, 1.0, 0.0, 0.77];
const BORDER_COLOR_INT: [GLint; 4] = [0x0800_0000, 0x7FFF_FFFF, 0, 0x0FFF_FFFF];

/// `TextureBorderColorCase`
fn texture_border_color_case(case: &mut ApiCase<'_>, target: GLenum, pname: GLenum, query_type: QueryType) {
    with_bound_texture(case, target, |case| {
        // border color is undefined if queried with pure type and was not set to pure value
        if matches!(
            query_type,
            QueryType::TextureParamIntegerVec4 | QueryType::TextureParamFloatVec4
        ) {
            // Initial
            verify_state_texture_param_float_vec4(case, target, pname, [0.0; 4], query_type);
        }

        match query_type {
            QueryType::TextureParamPureIntegerVec4 => {
                // SAFETY: four values for a four-valued parameter.
                unsafe {
                    case.gl()
                        .tex_parameter_iiv(target, pname, BORDER_COLOR_PURE_INT.as_ptr())
                };
                case.expect_error(glw::GL_NO_ERROR);

                verify_state_texture_param_integer_vec4(case, target, pname, BORDER_COLOR_PURE_INT, query_type);
            }
            QueryType::TextureParamPureUnsignedIntegerVec4 => {
                // SAFETY: as above.
                unsafe {
                    case.gl()
                        .tex_parameter_iuiv(target, pname, BORDER_COLOR_PURE_UINT.as_ptr())
                };
                case.expect_error(glw::GL_NO_ERROR);

                verify_state_texture_param_unsigned_integer_vec4(
                    case,
                    target,
                    pname,
                    BORDER_COLOR_PURE_UINT,
                    query_type,
                );
            }
            _ => {
                // SAFETY: as above.
                unsafe { case.gl().tex_parameterfv(target, pname, BORDER_COLOR_FLOAT.as_ptr()) };
                case.expect_error(glw::GL_NO_ERROR);

                verify_state_texture_param_float_vec4(case, target, pname, BORDER_COLOR_FLOAT, query_type);

                // SAFETY: as above.
                unsafe { case.gl().tex_parameteriv(target, pname, BORDER_COLOR_INT.as_ptr()) };
                case.expect_error(glw::GL_NO_ERROR);

                verify_state_texture_param_normalized_i32_vec4(case, target, pname, BORDER_COLOR_INT, query_type);
            }
        }
    });
}

/// `createIsTextureTest`. Upstream returns the case and the caller adds it; the port's
/// `add_api_case` does both, so the group comes in instead.
pub fn add_is_texture_test(group: &mut TestCaseGroup, name: String, target: GLenum) {
    add_api_case(group, name, move |case: &mut ApiCase<'_>| {
        let context_type = case.context().context_type();
        if !is_core_texture_target(context_type, target)
            && !check_required_extensions(case, texture_target_extension(target))
        {
            return;
        }

        let mut texture: GLuint = 0;
        // SAFETY: one name in, one name out.
        unsafe {
            case.gl().gen_textures(1, &mut texture);
            case.gl().bind_texture(target, texture);
        }
        case.expect_error(glw::GL_NO_ERROR);

        verify_state_texture_object_boolean(case, texture, true);

        // SAFETY: a name this case created.
        unsafe { case.gl().delete_textures(1, &texture) };
        case.expect_error(glw::GL_NO_ERROR);

        verify_state_texture_object_boolean(case, texture, false);
    });
}

/// `createTexParamTest`
pub fn add_tex_param_test(
    group: &mut TestCaseGroup,
    name: String,
    query_type: QueryType,
    target: GLenum,
    tester: TesterType,
    setter: Setter,
) {
    let pname = map_tester_to_pname(tester);
    add_api_case(group, name, move |case: &mut ApiCase<'_>| {
        if !require_texture_test_support(case, Some(target), tester, setter, query_type) {
            return;
        }

        match tester {
            TesterType::TextureMinLod | TesterType::TextureMaxLod => {
                texture_lod_case(case, target, pname, setter, query_type)
            }
            TesterType::TextureBaseLevel | TesterType::TextureMaxLevel => {
                texture_level_case(case, target, pname, setter, query_type)
            }
            TesterType::TextureImmutableLevels => texture_immutable_levels_case(case, target, pname, query_type),
            TesterType::TextureImmutableFormat => texture_immutable_format_case(case, target, pname, query_type),
            TesterType::DepthStencilTextureMode => texture_toggle_state_case(
                case,
                target,
                pname,
                setter,
                query_type,
                glw::GL_DEPTH_COMPONENT as GLint,
                glw::GL_STENCIL_INDEX as GLint,
            ),
            TesterType::TextureSrgbDecodeExt => {
                texture_toggle_state_case(
                    case,
                    target,
                    pname,
                    setter,
                    query_type,
                    glw::GL_DECODE_EXT as GLint,
                    glw::GL_SKIP_DECODE_EXT as GLint,
                );
            }
            TesterType::TextureBorderColor => texture_border_color_case(case, target, pname, query_type),
            TesterType::TextureWrapSClampToBorder
            | TesterType::TextureWrapTClampToBorder
            | TesterType::TextureWrapRClampToBorder => {
                texture_wrap_clamp_to_border_case(case, target, pname, query_type);
            }
            _ => texture_integer_state_case(case, target, pname, setter, query_type),
        }
    });
}

// ---------------------------------------------------------------------------------
// Sampler cases
// ---------------------------------------------------------------------------------

/// Runs `body` against a sampler object that lives only for the case, the way upstream's
/// `glu::Sampler` does.
fn with_sampler(case: &mut ApiCase<'_>, body: impl FnOnce(&mut ApiCase<'_>, GLuint)) {
    let mut sampler: GLuint = 0;
    // SAFETY: one name in, one name out, deleted below.
    unsafe { case.gl().gen_samplers(1, &mut sampler) };
    case.expect_error(glw::GL_NO_ERROR);

    body(case, sampler);

    // SAFETY: a name this function created.
    unsafe { case.gl().delete_samplers(1, &sampler) };
    case.expect_error(glw::GL_NO_ERROR);
}

/// `SamplerWrapCase`, `SamplerFilterCase`, `SamplerCompareModeCase` and
/// `SamplerCompareFuncCase` - the sampler half of `texture_integer_state_case`.
fn sampler_integer_state_case(case: &mut ApiCase<'_>, pname: GLenum, setter: Setter, query_type: QueryType) {
    let spec = integer_state_spec(pname);

    with_sampler(case, |case, sampler| {
        if !setter.is_pure() {
            verify_state_sampler_param_integer(case, sampler, pname, spec.initial, query_type);
        }

        if setter.is_pure() {
            for &value in &spec.values {
                sampler_parameter_pure(case, setter, sampler, pname, value);
                verify_state_sampler_param_integer(case, sampler, pname, value, query_type);
            }
        } else {
            for &value in &spec.values {
                sampler_parameteri(case, sampler, pname, value);
                verify_state_sampler_param_integer(case, sampler, pname, value, query_type);
            }

            // check unit conversions with float
            for &value in &spec.values {
                #[expect(clippy::cast_precision_loss, reason = "a GL enum is small enough to be exact in f32")]
                let as_float = value as f32;
                sampler_parameterf(case, sampler, pname, as_float);
                verify_state_sampler_param_integer(case, sampler, pname, value, query_type);
            }
        }
    });
}

/// `SamplerLODCase`
fn sampler_lod_case(case: &mut ApiCase<'_>, pname: GLenum, setter: Setter, query_type: QueryType) {
    let initial_value = if pname == glw::GL_TEXTURE_MIN_LOD { -1000 } else { 1000 };

    with_sampler(case, |case, sampler| {
        if (query_supports_signed(query_type) || initial_value >= 0) && !setter.is_pure() {
            verify_state_sampler_param_integer(case, sampler, pname, initial_value, query_type);
        }

        let num_iterations = 20;
        let mut rnd = Random::new(0xabcdef);

        match setter {
            Setter::PureInt => {
                for _ in 0..num_iterations {
                    let reference = rnd.get_int(-1000, 1000);
                    sampler_parameter_pure(case, setter, sampler, pname, reference);
                    #[expect(clippy::cast_precision_loss, reason = "the range is far inside f32's exact integers")]
                    let as_float = reference as f32;
                    verify_state_sampler_param_float(case, sampler, pname, as_float, query_type);
                }
            }
            Setter::PureUint => {
                for _ in 0..num_iterations {
                    let reference = rnd.get_int(0, 1000);
                    sampler_parameter_pure(case, setter, sampler, pname, reference);
                    #[expect(clippy::cast_precision_loss, reason = "as above")]
                    let as_float = reference as f32;
                    verify_state_sampler_param_float(case, sampler, pname, as_float, query_type);
                }
            }
            Setter::Default => {
                let min_limit = if query_supports_signed(query_type) { -1000 } else { 0 };

                for _ in 0..num_iterations {
                    #[expect(clippy::cast_precision_loss, reason = "as above")]
                    let reference = rnd.get_float_range(min_limit as f32, 1000.0);
                    sampler_parameterf(case, sampler, pname, reference);
                    verify_state_sampler_param_float(case, sampler, pname, reference, query_type);
                }

                // check unit conversions with int
                for _ in 0..num_iterations {
                    let reference = rnd.get_int(min_limit, 1000);
                    sampler_parameteri(case, sampler, pname, reference);
                    #[expect(clippy::cast_precision_loss, reason = "as above")]
                    let as_float = reference as f32;
                    verify_state_sampler_param_float(case, sampler, pname, as_float, query_type);
                }
            }
        }
    });
}

/// `SamplerSRGBDecodeCase`
fn sampler_srgb_decode_case(case: &mut ApiCase<'_>, pname: GLenum, setter: Setter, query_type: QueryType) {
    let decode = glw::GL_DECODE_EXT as GLint;
    let skip_decode = glw::GL_SKIP_DECODE_EXT as GLint;

    with_sampler(case, |case, sampler| {
        if !setter.is_pure() {
            // Initial
            verify_state_sampler_param_integer(case, sampler, pname, decode, query_type);
        }

        // Toggle - upstream runs this section for a pure setter too
        sampler_parameteri(case, sampler, pname, skip_decode);
        verify_state_sampler_param_integer(case, sampler, pname, skip_decode, query_type);

        sampler_parameteriv(case, sampler, pname, decode);
        verify_state_sampler_param_integer(case, sampler, pname, decode, query_type);

        #[expect(clippy::cast_precision_loss, reason = "a GL enum is small enough to be exact in f32")]
        let skip_decode_float = skip_decode as f32;
        sampler_parameterf(case, sampler, pname, skip_decode_float);
        verify_state_sampler_param_integer(case, sampler, pname, skip_decode, query_type);

        #[expect(clippy::cast_precision_loss, reason = "as above")]
        let decode_float = decode as f32;
        sampler_parameterfv(case, sampler, pname, decode_float);
        verify_state_sampler_param_integer(case, sampler, pname, decode, query_type);

        if setter.is_pure() {
            sampler_parameter_pure(case, setter, sampler, pname, skip_decode);
            verify_state_sampler_param_integer(case, sampler, pname, skip_decode, query_type);

            sampler_parameter_pure(case, setter, sampler, pname, decode);
            verify_state_sampler_param_integer(case, sampler, pname, decode, query_type);
        }
    });
}

/// `SamplerWrapClampToBorderCase`
fn sampler_wrap_clamp_to_border_case(case: &mut ApiCase<'_>, pname: GLenum, query_type: QueryType) {
    with_sampler(case, |case, sampler| {
        sampler_parameteri(case, sampler, pname, glw::GL_CLAMP_TO_BORDER_EXT as GLint);
        verify_state_sampler_param_integer(case, sampler, pname, glw::GL_CLAMP_TO_BORDER_EXT as GLint, query_type);

        sampler_parameteri(case, sampler, pname, glw::GL_REPEAT as GLint);

        #[expect(clippy::cast_precision_loss, reason = "a GL enum is small enough to be exact in f32")]
        let clamp_to_border = glw::GL_CLAMP_TO_BORDER_EXT as f32;
        sampler_parameterf(case, sampler, pname, clamp_to_border);

        verify_state_sampler_param_integer(case, sampler, pname, glw::GL_CLAMP_TO_BORDER_EXT as GLint, query_type);
    });
}

/// `SamplerBorderColorCase`
fn sampler_border_color_case(case: &mut ApiCase<'_>, pname: GLenum, query_type: QueryType) {
    with_sampler(case, |case, sampler| {
        // border color is undefined if queried with pure type and was not set to pure value
        if matches!(
            query_type,
            QueryType::SamplerParamIntegerVec4 | QueryType::SamplerParamFloatVec4
        ) {
            // Initial
            verify_state_sampler_param_float_vec4(case, sampler, pname, [0.0; 4], query_type);
        }

        match query_type {
            QueryType::SamplerParamPureIntegerVec4 => {
                // SAFETY: four values for a four-valued parameter.
                unsafe {
                    case.gl()
                        .sampler_parameter_iiv(sampler, pname, BORDER_COLOR_PURE_INT.as_ptr())
                };
                case.expect_error(glw::GL_NO_ERROR);

                verify_state_sampler_param_integer_vec4(case, sampler, pname, BORDER_COLOR_PURE_INT, query_type);
            }
            QueryType::SamplerParamPureUnsignedIntegerVec4 => {
                // SAFETY: as above.
                unsafe {
                    case.gl()
                        .sampler_parameter_iuiv(sampler, pname, BORDER_COLOR_PURE_UINT.as_ptr())
                };
                case.expect_error(glw::GL_NO_ERROR);

                verify_state_sampler_param_unsigned_integer_vec4(
                    case,
                    sampler,
                    pname,
                    BORDER_COLOR_PURE_UINT,
                    query_type,
                );
            }
            _ => {
                // SAFETY: as above.
                unsafe {
                    case.gl()
                        .sampler_parameterfv(sampler, pname, BORDER_COLOR_FLOAT.as_ptr())
                };
                case.expect_error(glw::GL_NO_ERROR);

                verify_state_sampler_param_float_vec4(case, sampler, pname, BORDER_COLOR_FLOAT, query_type);

                // SAFETY: as above.
                unsafe { case.gl().sampler_parameteriv(sampler, pname, BORDER_COLOR_INT.as_ptr()) };
                case.expect_error(glw::GL_NO_ERROR);

                verify_state_sampler_param_normalized_i32_vec4(case, sampler, pname, BORDER_COLOR_INT, query_type);
            }
        }
    });
}

/// `createSamplerParamTest`
pub fn add_sampler_param_test(
    group: &mut TestCaseGroup,
    name: String,
    query_type: QueryType,
    tester: TesterType,
    setter: Setter,
) {
    let pname = map_tester_to_pname(tester);
    add_api_case(group, name, move |case: &mut ApiCase<'_>| {
        if !require_texture_test_support(case, None, tester, setter, query_type) {
            return;
        }

        match tester {
            TesterType::TextureMinLod | TesterType::TextureMaxLod => sampler_lod_case(case, pname, setter, query_type),
            TesterType::TextureSrgbDecodeExt => sampler_srgb_decode_case(case, pname, setter, query_type),
            TesterType::TextureBorderColor => sampler_border_color_case(case, pname, query_type),
            TesterType::TextureWrapSClampToBorder
            | TesterType::TextureWrapTClampToBorder
            | TesterType::TextureWrapRClampToBorder => {
                sampler_wrap_clamp_to_border_case(case, pname, query_type);
            }
            _ => sampler_integer_state_case(case, pname, setter, query_type),
        }
    });
}
